def send_telegram(message):                       

    try:                                            

        r = requests.post(                         
            f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage",  
            json={                                 
                "chat_id": CHAT_ID,                 
                "text": message                     
            },                                     
            timeout=20                             
        )                                          

        if r.status_code == 200:                   
            return True                            

        print(                                     
            "TELEGRAM SEND FAILED:",                
            r.status_code,                         
            r.text                                 
        )                                           

        return False                               

    except Exception as e:                         

        print("TELEGRAM ERROR")                    
        print(repr(e))                              

        return False                               

