def send_prematch_signal(        

    fixture_id,                  

    match_date,                 
    kickoff_time,                

    country,                     
    league,                      

    home,                        
    away,                        

    market,                       

    confidence,                  
    probability,                  
    odds_text                     

):                                

    message = f"""               
🔥 PREMATCH V3

🏆 {home} vs {away}

🗓 Date: {match_date}
🕒 Kickoff: {kickoff_time}

🌍 {country}
🏟 {league}

🔥📊 Market:
{market}🔥

🎯 Probability:
{probability}%

💰 Odds:
{odds_text}

💎 Confidence:
{confidence}%
"""                               

    sent_ok = send_telegram(message)                

    if not sent_ok:                                 
        return False                              
    try:                                           
        odd_value = float(odds_text)               
    except (ValueError, TypeError):                
        odd_value = 0.0                            

    save_signal(                  

        fixture_id,               

        country,                  
        league,                   

        home,                     
        away,                    

        market,                   

        odd_value,                       
        confidence               

    )                             
                                    
    print(                                   
        "SIGNAL SAVED:",                     
        fixture_id,                           
        market,                               
        confidence                           
    )                                        

    return True                                       

